// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {createGraphVertexCache, graphClipTransform} from "../../../main/frontend/graph-explorer/graph-webgl.ts";

test('hybrid WebGL draws routed, clipped curves instead of center-to-center shortcuts', () => {
  const graph = {nodes: [{id: 'a', x: -100, y: 0}, {id: 'b', x: 100, y: 0}], edges: [{id: 'ab', source: 'a', target: 'b'}]};
  const curves = new Map([['ab', {path: '', start: {x: -50, y: 0}, control: {x: 0, y: 100}, end: {x: 50, y: 0}}]]);
  const cache = createGraphVertexCache(), first = cache(graph, curves);
  assert.equal(first.lines[0], -50);
  assert.equal(first.lines.at(-2), 50);
  assert.ok([...first.lines].some((value, i) => i % 2 === 1 && value > 40));
  assert.equal(cache(graph, curves), first, 'pan/zoom must reuse sampled curves');
  assert.notEqual(cache(graph, new Map(curves)), first, 'new routing invalidates the GPU cache');
});

test("pan/zoom reuse vertex arrays; position and topology edits invalidate them", () => {
  const cache = createGraphVertexCache();
  const graph = {nodes: [{id: "a", x: 4, y: 8}, {id: "b", x: 12, y: 20}], edges: [{source: "a", target: "b"}]};
  const initial = cache(graph);
  assert.deepEqual([...initial.lines], [4, 8, 12, 20]);
  for (let i = 0; i < 600; i++) assert.equal(cache({...graph}), initial);
  const moved = cache({...graph, nodes: graph.nodes.map(node => ({...node, x: node.x + 1}))});
  assert.notEqual(moved, initial);
  assert.deepEqual([...moved.lines], [5, 8, 13, 20]);
  assert.equal(cache({...graph, edges: []}).lines.length, 0);
});

test("GPU viewport transform matches SVG meet scaling at all tested aspect ratios", () => {
  for (const [width, height] of [[1280, 780], [390, 844], [1200, 300], [0, 0]]) {
    for (const transform of [{x: 0, y: 0, k: 1}, {x: 230, y: -57, k: .24}, {x: -328, y: 201, k: 2.8}]) {
      const matrix = graphClipTransform(transform, width, height);
      const w = width || 1280, h = height || 780, meet = Math.min(w / 1280, h / 780);
      for (const [x, y] of [[0, 0], [1280, 780], [640, 390], [-1000, 4900]]) {
        const expectedX = 2 * ((x * transform.k + transform.x) * meet + (w - 1280 * meet) / 2) / w - 1;
        const expectedY = 1 - 2 * ((y * transform.k + transform.y) * meet + (h - 780 * meet) / 2) / h;
        assert.ok(Math.abs(x * matrix.scaleX + matrix.offsetX - expectedX) < 1e-12);
        assert.ok(Math.abs(y * matrix.scaleY + matrix.offsetY - expectedY) < 1e-12);
      }
    }
  }
});
